/**
 * # سجلُّ التجاوزِ المُصنَّف — القائمةُ المغلقةُ الوحيدة
 *
 * **الغرض:** أن يكون في المستودعِ موضعٌ **واحدٌ** يُعلَن فيه كلُّ اختبارٍ يُتجاوَز،
 * ومعه أربعةُ أشياءَ لا يمرّ مدخلٌ بلا واحدٍ منها: **سببُ** التجاوزِ، و**شرطُ
 * تفعيلِه**، و**مالكُه**، و**المسارُ الحرجُ** الذي يخدمه إن كان يخدم واحداً. ثم
 * حيثُ يعمل فعلاً (`runsIn`) — أو بيانٌ مكتوبٌ أنّه لا يعمل في مكانٍ (`whyNotRun`).
 *
 * **الحالة:** `OPS-009` — مُنفَّذ · مُختبَر (ADR 0046). والأعدادُ **مقيسةٌ** بتشغيلِ
 * كلِّ ملفٍّ منفرداً يومَ 2026-08-29: خمسةٌ وخمسون ملفّاً و**514** حالةً متجاوَزةً،
 * وهو العددُ نفسُه الذي يذكره البندُ في القسم 11-د. ثمّ زاد يومَ 2026-08-30 مدخلٌ
 * سادسٌ وخمسون باثنتَي عشرةَ حالةً مقيسةً — ملفُّ `OPS-006` الذي يعمل على Redis حقيقيٍّ في
 * وظيفتِه وحدَها ويُتجاوَز حيث لا نقطةَ له، فصار المجموعُ **526**. ثمّ زاد يومَ
 * 2026-09-02 مدخلٌ سابعٌ وخمسون بثمانِ حالاتٍ مقيسةٍ — حزمةُ ترتيبِ أحداثِ التتبُّعِ
 * (`BUG-009`) التي شرطَ `ADR 0053 §٨` قاعدةَ PostgreSQL حقيقيّةً لحالتَيها ١ و٧،
 * فصار المجموعُ **534**. والزيادةُ تُعلَن
 * ولا تُدمَج في رقمِ `OPS-009`: ذاك قياسُ يومِه لا سقفٌ للمستودعِ.
 *
 * **ينتمي إلى:** البند `OPS-009` · القسم 11-د · القيدَ «لا يُطلَق تجارياً وبها
 * تجاوزٌ على مسارٍ حرج».
 *
 * **يُتوقع أن يستخدمه لاحقاً:** `scripts/check-skip-classification.ts` (يطابقه
 * بالشيفرةِ وبملفِّ سيرِ العمل) · `scripts/check-no-skipped-tests.ts` (يطابقه
 * بمخرجاتِ التشغيلِ الحقيقيّ) · واختباراتُ الوحدة.
 *
 * **ملاحظات مستقبلية:** كلُّ ملفِّ اختبارٍ جديدٍ فيه تجاوزٌ يُضاف ههنا أو يسقط
 * البناء. ومتى صار لقاعدةِ القياسِ مُشغِّلٌ في CI انتقل مدخلُ `bench-reset-seed`
 * من `whyNotRun` إلى `runsIn` — ولا يُحذَف البيانُ بل يُستبدَل بمُشغِّلٍ.
 *
 * **ما لا يفعله هذا الملفُّ عن قصدٍ — وحدودُه مُعلَنةٌ لا مضمرةٌ:**
 * - **ليس إذناً بالتجاوز.** التسجيلُ يُخرِج التجاوزَ من الصمتِ إلى العلن؛ ولا
 *   يُبرِّره. والتجاوزُ على مسارٍ حرجٍ بلا مُشغِّلٍ **يُسقِط البناءَ** ولا يُقبَل مدخلاً.
 * - **لا يفرض عددَ الحالات.** `skipped` مقيسٌ يومَ التصنيفِ ومرجعٌ للقارئ؛ ولو
 *   فُرِض لأسقطت كلُّ حالةٍ جديدةٍ البناءَ فضُغِط على تخفيفِ الحاجزِ نفسِه.
 * - **لا يعرف شيئاً عن البيئةِ ولا يقرأ قرصاً.** بياناتٌ مُجمَّدةٌ فقط.
 * - **لا يحرس شيئاً.** الفرضُ في الحاجزَين وحدَهما.
 */

/**
 * المالكُ: قائمةٌ **مغلقةٌ** من طرفَين لا أكثر. ومعنى المِلكيّةِ ههنا: **مَن يملك
 * إزالةَ سببِ التجاوز**. فما كان سببُه داخلَ المستودعِ (خطوةُ CI، حاويةٌ، شيفرةٌ)
 * فمالكُه المنفِّذُ؛ وما كان سببُه قراراً أو مورداً خارجياً فمالكُه مديرُ المشروع.
 */
export const SKIP_OWNERS = ["منفّذ المستودع", "مدير المشروع"] as const;
export type SkipOwner = (typeof SKIP_OWNERS)[number];

/**
 * المساراتُ الحرجةُ: قائمةٌ **مغلقةٌ** مأخوذةٌ من أقسامِ خارطةِ الطريقِ لا من رأسِ
 * الكاتب. ومعنى «حرج» ههنا: مسارٌ إن انكسر في الإنتاجِ خسِر المستخدمُ مالاً أو
 * سلامةً أو ثقةً بلا طريقٍ للتراجعِ اليدويّ. و`null` تعني: خارجَ هذه القائمةِ —
 * لا تعني «غيرَ مهمّ».
 */
export const CRITICAL_PATHS = [
  "الهويةُ والجلسةُ والصلاحيات",
  "دورةُ الرحلةِ والإسناد",
  "التتبّعُ وموقعُ السائق",
  "الدفعُ والاشتراك",
  "السلامةُ والاستغاثة",
  "المخطّطُ وتفعيلُ المدن",
  "النسخُ والاستعادة",
  "المهامُّ الدوريةُ والقفلُ الموزَّع",
  "توثيقُ السائق",
  // زيادةٌ تُقرأُ معَ ما قبلَها (`ح-8`): أرقامُ «حصيلتي» ليسَت من
  // دورةِ الرحلةِ ولا من الدفعِ: رحلةٌ تتمُّ سليمةً والرقمُ المعروضُ عنها
  // كاذبٌ فلا يسقُطُ شيءٌ، والضررُ ثقةٌ تُفقَدُ ولا تُستردُّ. فلها اسمٌ منفردٌ
  // لأنَّ تصنيفَها تحتَ غيرِها يُخفي أيَّ مسارٍ بقيَ بلا قياسٍ.
  "شفافيّةُ الأداءِ والحصيلة",
  // زيادةٌ تُقرأُ معَ ما قبلَها (`ح-8`): اقتصادُ التشغيلِ (القسمُ 17) ليسَ من
  // دورةِ الرحلةِ ولا من الدفعِ: كلُّ رحلةٍ تتمُّ سليمةً وكلُّ اختبارٍ أخضرُ،
  // والنداءُ الزائدُ إلى مزوّدٍ مدفوعٍ لا يظهرُ في أيِّ حالةٍ حتّى تصلَ الفاتورةُ.
  // فله اسمٌ منفردٌ لأنَّ تصنيفَه تحتَ «التتبّعِ» يُخفي أيَّ نداءٍ بقيَ بلا عدٍّ.
  "الاستدامةُ الاقتصاديّةُ",
] as const;
export type CriticalPath = (typeof CRITICAL_PATHS)[number];

/** مدخلٌ واحدٌ = ملفُّ اختبارٍ واحدٌ فيه تجاوزٌ مشروطٌ. */
export interface SkipEntry {
  /** المسارُ النسبيُّ من جذرِ المستودع. */
  readonly file: string;
  /** عناوينُ الحزمِ المعلَّقةِ في الملفِّ كما هي مكتوبةٌ فيه. */
  readonly suites: readonly string[];
  /** عددُ الحالاتِ المتجاوَزةِ **مقيساً** يومَ التصنيف — مرجعٌ لا شرطٌ. */
  readonly skipped: number;
  /** اسمُ متغيّرِ البيئةِ الذي يُعلِّق التجاوزَ — والحاجزُ يتحقّق أنّ الملفَّ يقرؤه. */
  readonly gate: string;
  readonly reason: string;
  readonly activation: string;
  readonly owner: SkipOwner;
  readonly criticalPath: CriticalPath | null;
  /** اسمُ خطوةِ CI التي تُشغِّله فعلاً، أو `null` إن لم يُشغِّله شيءٌ اليوم. */
  readonly runsIn: string | null;
  /** بيانُ سببِ عدمِ التشغيلِ — إلزاميٌّ متى كان `runsIn` معدوماً، ومحرَّمٌ خلافَ ذلك. */
  readonly whyNotRun: string | null;
}

